// ===== DRAFT REVIEW RULES. "approved" only means ready to copy: nothing is ever sent from here. =====
const MAX_ON_PAGE = 10;
const DECISIONS = ['keep pending', 'approved', 'edit', 'rejected'];
const esc = (t) => String(t === null || t === undefined ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

function buildReviewPage(drafts) {
  const pending = drafts.filter((d) => d.id && d.review_status === 'pending review')
    .sort((a, b) => String(a.created_at).localeCompare(String(b.created_at)) || Number(a.id) - Number(b.id))
    .slice(0, MAX_ON_PAGE);
  const fields = [];
  pending.forEach((d) => {
    const checks = d.check_passed === true || d.check_passed === 'true'
      ? '<p>Code checks: passed</p>'
      : '<p><strong>Code checks failed:</strong> ' + esc(d.check_notes) + '</p>';
    fields.push({ fieldType: 'html', elementName: 'draft_' + d.id,
      html: '<hr><h3>Draft ' + d.id + ' · ' + esc(d.project_id) + ' · ' + esc(d.kind) + '</h3>' + checks +
        '<p><strong>Subject:</strong> ' + esc(d.subject) + '</p><p>' + esc(d.body).replace(/\n/g, '<br>') + '</p>' });
    fields.push({ fieldLabel: 'Decision for draft ' + d.id, fieldName: 'decision_' + d.id, fieldType: 'dropdown',
      fieldOptions: { values: DECISIONS.map((o) => ({ option: o })) }, requiredField: false });
    fields.push({ fieldLabel: 'Note for draft ' + d.id, fieldName: 'note_' + d.id, fieldType: 'textarea', requiredField: false });
  });
  return { has_pending: pending.length > 0, draft_ids: pending.map((d) => d.id), form_fields: fields,
    waiting_total: drafts.filter((d) => d.id && d.review_status === 'pending review').length };
}

// answers: what the form returned. A draft that failed the code checks can only be approved with a note.
function prepareDecisions(answers, drafts, draftIds) {
  const updates = [];
  const kept = [];
  draftIds.forEach((id) => {
    const d = drafts.find((x) => String(x.id) === String(id)) || {};
    const decision = String(answers['decision_' + id] ?? answers['Decision for draft ' + id] ?? '').trim();
    const note = String(answers['note_' + id] ?? answers['Note for draft ' + id] ?? '').trim();
    const passed = d.check_passed === true || d.check_passed === 'true';
    if (!decision || decision === 'keep pending') kept.push({ id, reason: 'no decision' });
    else if (!DECISIONS.includes(decision)) kept.push({ id, reason: 'unknown decision ' + decision });
    else if (decision === 'approved' && !passed && !note) kept.push({ id, reason: 'failed checks: approval needs a note' });
    else if ((decision === 'edit' || decision === 'rejected') && !note) kept.push({ id, reason: decision + ' needs a note saying what to change' });
    else updates.push({ row_id: id, review_status: decision, reviewer_note: note });
  });
  return { updates, kept };
}
// ===== end of review rules =====

// Test mode brings its own drafts and answers, so it never touches the real table.
const evalRun = $('When called by eval').isExecuted;
const e = evalRun ? $('When called by eval').first().json : {};
const drafts = evalRun ? (e.eval_drafts || []) : $input.all().map((i) => i.json).filter((d) => d.id);
const page = buildReviewPage(drafts);
const out = { ...page, eval_run: evalRun };
if (evalRun) out.result = prepareDecisions(e.eval_answers || {}, drafts, page.draft_ids);
return [{ json: out }];

