const r = $('Prepare decisions').first().json;
const count = (s) => r.updates.filter((u) => u.review_status === s).length;
const kept = r.kept.filter((k) => k.reason !== 'no decision');
return [{ json: { summary: 'Saved: ' + count('approved') + ' approved, ' + count('edit') + ' to edit, ' + count('rejected') + ' rejected.' +
